export function ReviewArtwork({ id, label, size }: { id?: string; label: string; size: number }) {
  const { colors } = useTheme();
  const source = id ? REVIEW_ART[id] : undefined;
  return <View accessibilityLabel={label} style={{ width: size, height: size, flexShrink: 0, borderRadius: Math.max(4, size * .1), borderWidth: 1, borderColor: colors.gold, backgroundColor: colors.panel2, overflow: "hidden", alignItems: "center", justifyContent: "center" }}>
    {source ? <Image source={source} resizeMode="contain" fadeDuration={0} style={{ width: "94%", height: "94%" }} /> : <Text numberOfLines={1} style={{ color: colors.muted, fontSize: Math.max(7, Math.min(14, size * .23)), fontWeight: "800" }}>{label.split(" ").filter(Boolean).slice(0, 2).map(word => word[0]).join("").toUpperCase()}</Text>}
  </View>;
}
